# ======================== запись ========================
wb = load_workbook(PATH)
ws = wb["Работы"]
start = ws.max_row + 1
n0 = ws.max_row - 1  # последний № в существующей таблице
for i, r in enumerate(rows):
    excel_row = start + i
    for col in range(1, 15):
        c = ws.cell(row=excel_row, column=col)
        ref = ws.cell(row=2, column=col)
        c.font = copy.copy(ref.font)
        c.border = copy.copy(ref.border)
        c.fill = copy.copy(ref.fill)
        c.alignment = copy.copy(ref.alignment)
        c.number_format = ref.number_format
        c.protection = copy.copy(ref.protection)
    ws.cell(row=excel_row, column=1).value = n0 + 1 + i
    for j, val in enumerate(r):
        ws.cell(row=excel_row, column=j + 2).value = val
ws.auto_filter.ref = "A1:N%d" % (start + len(rows) - 1)
wb.save(PATH)
print("added rows:", len(rows), "| new last row:", start + len(rows) - 1, "| № from", n0 + 1, "to", n0 + len(rows))
